func double(_ x: Int) -> Int { x * 2 }
let f: (Int) -> Int = double
print(f(4))

func add(_ a: Int) -> (Int) -> Int {
    { b in a + b }
}
let addTen = add(10)
print(addTen(5))
print(add(1)(2))

func then<A, B, C>(_ f: @escaping (A) -> B,
    _ g: @escaping (B) -> C) -> (A) -> C {
    { g(f($0)) }
}
let h = then({ $0 + 1 }, { $0 * 3 })
print(h(2))

